<div class="stats-grid"><?php foreach([['Total members',$stats['members'],'♙','purple','All registered members'],['Active members',$stats['active'],'✓','green','Currently active'],['Trainers',$stats['trainers'],'♟','orange','Your coaching team'],["Today's check-ins",$stats['today'],'◷','blue','Attendance recorded today']] as $s): ?><div class="stat-card"><div class="stat-top"><span><?= $s[0] ?></span><span class="stat-icon <?= $s[3] ?>"><?= $s[2] ?></span></div><strong><?= $s[1] ?></strong><small><?= $s[4] ?></small></div><?php endforeach; ?></div>
